import React, { useEffect, useState, useRef } from 'react';
import {
  Box,
  Button,
  Chip,
  InputAdornment,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import usePageQuery from '../../core/hooks/usePageQuery';
import { Table } from '@tanstack/react-table';
import ReactTable from '../../components/Table/ReactTable';
import PosTablePagination from '../../components/Table/PosTablePagination';
import { useDeleteSupplierManageMutation } from '../posApi';
import { useTranslation } from 'react-i18next';
import { useReactToPrint } from 'react-to-print';
import useSupplier from '../../core/hooks/useUser';
import useSupplierList from './useSupplierList';
import NewSupplier from './components/NewSupplier';
import AnimatedPage from '../../layouts/AnimatedPage';
import AddIcon from '@mui/icons-material/Add';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import SearchIcon from '@mui/icons-material/Search';
import DeletePopup from '../../components/ModelPopup/DeletePopup';
import { useNotifier } from '../../core/Notifier';
import { Privileges } from '../../core/types/commonType';
import PayPopup from './components/PayPopup';
import { ISupplierDetailsData } from '../../core/Interface/supplier.interface';
import { HEADER_GRADIENT } from '../../theme/appColors';

const SupplierManagementPage = () => {
  const { setPage } = usePageQuery();
  const { t } = useTranslation(['common', 'suppliermanage']);
  const [supplierManageData, setSupplierManageData] = React.useState<ISupplierDetailsData | undefined>();
  const { userHasRight } = useSupplier();
  const { showErrorMessage, showMessage } = useNotifier();
  const [openAddSupplierManage, setOpenAddSupplierManage] = useState(false);
  const [openPayPopup, setOpenPayPopup] = React.useState(false);
  const [openDeleteSupplierManage, setOpenDeleteSupplierManage] = useState(false);
  const [supplierManageNameToDelete, setSupplierManageNameToDelete] = useState('');
  const [supplierToDelete, setSupplierToDelete] = useState<ISupplierDetailsData | null>(null);
  const [localSearch, setLocalSearch] = useState('');

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    table.setPageSize(parseInt(event.target.value, 10));
  };

  const handleEdit = (data: ISupplierDetailsData) => {
    setSupplierManageData(data);
    setOpenAddSupplierManage(true);
  };

  const handlePayment = (data: ISupplierDetailsData) => {
    setSupplierManageData(data);
    setOpenPayPopup(true);
  };

  const [deleteSupplierManage] = useDeleteSupplierManageMutation();

  const handleDelete = (data: ISupplierDetailsData) => {
    setSupplierToDelete(data);
    setOpenDeleteSupplierManage(true);
    setSupplierManageNameToDelete(data.supplierName);
  };

  const handleConfirmDelete = async () => {
    if (!supplierToDelete) return;
    try {
      const response = await deleteSupplierManage(supplierToDelete.id.toString()).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenDeleteSupplierManage(false);
        setSupplierToDelete(null);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const { table, isLoading, totalCount, setSearchText, isImageEnabled } =
    useSupplierList(handlePayment, handleEdit, handleDelete);

  useEffect(() => {
    if (
      !isLoading &&
      table.getState().pagination.pageIndex !== 0 &&
      table.getRowModel().rows.length === 0
    ) {
      setPage(0);
    }
  }, [isLoading, setPage, table]);

  const componentRef = useRef<HTMLDivElement | null>(null);
  const handlePrint = useReactToPrint({ content: () => componentRef.current });

  useEffect(() => {
    const timer = setTimeout(() => {
      if (supplierManageData && componentRef.current) handlePrint();
    }, 10);
    return () => clearTimeout(timer);
  }, [supplierManageData, componentRef, handlePrint]);

  const handleSearch = (text: string) => setSearchText(text);

  return (
    <AnimatedPage>
      <Box data-testid="supplier-management">
        {/* Hero Panel */}
        <Paper
          elevation={0}
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: 2,
            mb: 2,
            overflow: 'hidden',
          }}
        >
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              flexWrap: 'wrap',
              gap: 2,
              justifyContent: 'space-between',
              px: 3,
              py: 2,
            }}
          >
            {/* Title */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  background: 'rgba(255,255,255,0.15)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 40,
                  justifyContent: 'center',
                  width: 40,
                }}
              >
                <LocalShippingOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontSize: 18, fontWeight: 800, lineHeight: 1.2 }}>
                  Supplier Management
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 12, fontWeight: 500 }}>
                  All suppliers
                </Typography>
              </Box>
              {totalCount > 0 && (
                <Chip
                  label={`${totalCount} records`}
                  size="small"
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    color: '#fff',
                    fontSize: 11,
                    fontWeight: 600,
                  }}
                />
              )}
            </Box>

            {/* Search + Add */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: '10px' }}>
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 18 }} />
                    </InputAdornment>
                  ),
                }}
                onChange={(e) => setLocalSearch(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') handleSearch(localSearch); }}
                placeholder="Search name or mobile number…"
                size="small"
                sx={{
                  minWidth: 260,
                  '& .MuiOutlinedInput-root': {
                    background: 'rgba(255,255,255,0.12)',
                    borderRadius: '8px',
                    color: '#fff',
                    height: 40,
                    '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                    '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                    '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.8)' },
                    '& input::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 },
                  },
                }}
                value={localSearch}
                variant="outlined"
              />
              <Button
                onClick={() => handleSearch(localSearch)}
                sx={{
                  background: 'rgba(255,255,255,0.15)',
                  border: '1px solid rgba(255,255,255,0.3)',
                  borderRadius: '8px',
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 600,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'rgba(255,255,255,0.25)' },
                }}
                variant="contained"
              >
                {t('common:search')}
              </Button>

              {userHasRight(Privileges.SupplierManageAdd) && (
                <Button
                  onClick={() => { setSupplierManageData(undefined); setOpenAddSupplierManage(true); }}
                  startIcon={<AddIcon />}
                  sx={{
                    background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                    borderRadius: '8px',
                    boxShadow: '0 4px 14px rgba(37,99,235,0.35)',
                    color: '#fff',
                    flexShrink: 0,
                    fontWeight: 700,
                    height: 40,
                    px: 2.5,
                    '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                  }}
                  variant="contained"
                >
                  Supplier
                </Button>
              )}
            </Box>
          </Box>
        </Paper>

        {/* Table */}
        <Paper
          elevation={0}
          sx={{
            border: '1px solid #E2E8F0',
            borderRadius: 2,
            overflow: 'hidden',
          }}
        >
          <Box sx={{ maxWidth: '100%', minHeight: 480, overflow: 'auto' }}>
            <ReactTable isLoading={isLoading} {...(table as Table<object>)} />
          </Box>

          {table.getTotalSize() !== 0 && (
            <PosTablePagination
              count={totalCount}
              data-testid="pos-pagination"
              onPageChange={handlePaginationChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={table.getState().pagination.pageIndex}
              rowsPerPage={table.getState().pagination.pageSize}
              rowsPerPageOptions={[5, 10, 20]}
            />
          )}
        </Paper>

        {openAddSupplierManage && (
          <NewSupplier
            data={supplierManageData}
            handleCloseDialog={() => setOpenAddSupplierManage(false)}
            isImageEnabled={isImageEnabled}
            openModel={openAddSupplierManage}
            title={`${supplierManageData ? t('suppliermanage:edit') : t('suppliermanage:addNewSupplier')}`}
          />
        )}

        {openPayPopup && (
          <PayPopup
            data={supplierManageData}
            handleCloseDialog={() => setOpenPayPopup(false)}
            openModel={openPayPopup}
            title={`${supplierManageData ? t('suppliermanage:amount') : t('suppliermanage:addSupplier')}`}
          />
        )}

        {openDeleteSupplierManage && (
          <DeletePopup
            content={`${t('suppliermanage:confirmMessage')} "${supplierManageNameToDelete}"?`}
            handleCloseDelete={() => setOpenDeleteSupplierManage(false)}
            onConfirm={handleConfirmDelete}
            open={openDeleteSupplierManage}
            title={t('suppliermanage:deleteSupplier')}
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default SupplierManagementPage;
