import React from 'react';
import { ColumnDef } from '@tanstack/react-table';
import { Box, Tooltip, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { useTranslation } from 'react-i18next';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import VisibilityIcon from '@mui/icons-material/Visibility';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import useUser from '../../core/hooks/useUser';
import { Privileges } from '../../core/types/commonType';
import { useNavigate } from 'react-router-dom';
import { ISupplierDetailsData } from '../../core/Interface/supplier.interface';

const AVATAR_COLORS = [
  '#0F8B8D', '#2563EB', '#7c3aed', '#059669',
  '#D97706', '#DC2626', '#0891B2', '#4F46E5',
];

const avatarColor = (name: string) => {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) & 0xff;
  return AVATAR_COLORS[h % AVATAR_COLORS.length];
};

const ActionBtn = ({
  onClick, title, color, children, show = true,
}: {
  onClick: () => void; title: string; color: string;
  children: React.ReactNode; show?: boolean;
}) => {
  if (!show) return null;
  return (
    <Tooltip arrow title={title}>
      <Box
        onClick={(e) => { e.stopPropagation(); onClick(); }}
        sx={{
          alignItems: 'center',
          background: alpha(color, 0.1),
          border: `1px solid ${alpha(color, 0.22)}`,
          borderRadius: '7px',
          color,
          cursor: 'pointer',
          display: 'flex',
          height: 30,
          justifyContent: 'center',
          transition: 'all 0.15s',
          width: 30,
          '&:hover': { background: color, color: '#fff', transform: 'scale(1.07)' },
        }}
      >
        {children}
      </Box>
    </Tooltip>
  );
};

const useSupplierListColumn = ({
  handlePayment,
  handleEdit,
  handleDelete,
}: {
  handlePayment: (data: ISupplierDetailsData) => void;
  handleEdit: (data: ISupplierDetailsData) => void;
  handleDelete: (data: ISupplierDetailsData) => void;
}) => {
  const { t } = useTranslation(['suppliermanage']);
  const { userHasRight } = useUser();
  const navigate = useNavigate();

  return [
    {
      accessorKey: 'sn',
      header: '#',
      size: 52,
      cell: (cell) => (
        <Typography sx={{ color: alpha('#0F1D4D', 0.45), fontSize: 13, fontWeight: 600 }}>
          {cell.getValue() as number}
        </Typography>
      ),
    },
    {
      accessorKey: 'supplierName',
      header: t('suppliermanage:title.suppliername'),
      size: 200,
      cell: (cell) => {
        const name = (cell.getValue() as string) ?? '';
        const color = avatarColor(name);
        const initials = name.split(' ').slice(0, 2).map((w) => w[0]?.toUpperCase()).join('');
        return (
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.25 }}>
            <Box
              sx={{
                alignItems: 'center',
                background: alpha(color, 0.12),
                border: `1px solid ${alpha(color, 0.22)}`,
                borderRadius: '8px',
                color,
                display: 'flex',
                flexShrink: 0,
                fontSize: 11,
                fontWeight: 800,
                height: 30,
                justifyContent: 'center',
                width: 30,
              }}
            >
              {initials || '?'}
            </Box>
            <Typography sx={{ color: '#0F1D4D', fontSize: 13, fontWeight: 600 }}>
              {name}
            </Typography>
          </Box>
        );
      },
    },
    {
      accessorKey: 'contactPerson',
      header: t('suppliermanage:title.contactPerson'),
      size: 160,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      accessorKey: 'email',
      header: t('suppliermanage:title.email'),
      size: 180,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      accessorKey: 'mobile',
      header: t('suppliermanage:title.mobile'),
      size: 130,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      id: 'actions',
      header: '',
      size: 130,
      cell: (cell) => {
        const data = cell.row.original;
        return (
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75, justifyContent: 'flex-end' }}>
            <ActionBtn
              color="#0F8B8D"
              onClick={() => navigate(`/supplier-management-history/${data.id}`)}
              show={userHasRight(Privileges.CreditManagement)}
              title="View History"
            >
              <VisibilityIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
            <ActionBtn
              color="#059669"
              onClick={() => handlePayment(data)}
              show={userHasRight(Privileges.CreditManagement)}
              title="Add Payment"
            >
              <AttachMoneyIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
            <ActionBtn
              color="#D97706"
              onClick={() => handleEdit(data)}
              show={userHasRight(Privileges.SupplierManageEdit)}
              title="Edit Supplier"
            >
              <EditIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
            <ActionBtn
              color="#DC2626"
              onClick={() => handleDelete(data)}
              show={userHasRight(Privileges.SupplierManageDelete)}
              title="Delete Supplier"
            >
              <DeleteIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
          </Box>
        );
      },
    },
  ] as ColumnDef<ISupplierDetailsData>[];
};

export default useSupplierListColumn;
